CREATE OR REPLACE FUNCTION public.set_shelf_life_on_operation_done(p_table text, p_operation text, p_new jsonb, p_old jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_old_status TEXT;
  v_new_status TEXT;
BEGIN
  IF p_operation <> 'UPDATE' THEN
    RETURN;
  END IF;

  v_new_status := p_new->>'status';
  IF v_new_status <> 'Done' THEN
    RETURN;
  END IF;

  v_old_status := p_old->>'status';
  IF v_old_status = 'Done' THEN
    RETURN;
  END IF;

  PERFORM set_shelf_life_for_operation(p_new->>'id', 'After');
END;
$function$;

CREATE OR REPLACE FUNCTION public.set_shelf_life_on_operation_started(p_table text, p_operation text, p_new jsonb, p_old jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_old_status TEXT;
  v_new_status TEXT;
BEGIN
  IF p_operation <> 'UPDATE' THEN
    RETURN;
  END IF;

  v_new_status := p_new->>'status';
  IF v_new_status <> 'In Progress' THEN
    RETURN;
  END IF;

  v_old_status := p_old->>'status';
  IF v_old_status = 'In Progress' THEN
    RETURN;
  END IF;

  PERFORM set_shelf_life_for_operation(p_new->>'id', 'Before');
END;
$function$;

CREATE OR REPLACE FUNCTION public.storage_unit_block_location_change_with_children(p_table text, p_operation text, p_new jsonb, p_old jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_id              TEXT;
  v_new_location    TEXT;
  v_old_location    TEXT;
BEGIN
  IF p_operation <> 'UPDATE' THEN
    RETURN;
  END IF;

  v_new_location := p_new->>'locationId';
  v_old_location := p_old->>'locationId';

  IF v_new_location IS NOT DISTINCT FROM v_old_location THEN
    RETURN;
  END IF;

  v_id := p_old->>'id';

  IF EXISTS (SELECT 1 FROM "storageUnit" WHERE "parentId" = v_id) THEN
    RAISE EXCEPTION
      'Cannot change locationId of storage unit % because it has child units',
      v_id;
  END IF;
END;
$function$;

CREATE OR REPLACE FUNCTION public.storage_unit_enforce_no_cycle(p_table text, p_operation text, p_new jsonb, p_old jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_self_id   TEXT;
  v_cursor_id TEXT;
  v_depth     INTEGER := 0;
BEGIN
  IF p_operation NOT IN ('INSERT', 'UPDATE') THEN
    RETURN;
  END IF;

  v_cursor_id := p_new->>'parentId';
  IF v_cursor_id IS NULL THEN
    RETURN;
  END IF;

  v_self_id := p_new->>'id';

  WHILE v_cursor_id IS NOT NULL LOOP
    IF v_cursor_id = v_self_id THEN
      RAISE EXCEPTION 'Cycle detected in storage unit hierarchy at %', v_self_id;
    END IF;

    v_depth := v_depth + 1;
    IF v_depth > 1000 THEN
      RAISE EXCEPTION 'Storage unit hierarchy exceeds max depth (possible cycle)';
    END IF;

    SELECT "parentId" INTO v_cursor_id
    FROM "storageUnit"
    WHERE "id" = v_cursor_id;
  END LOOP;
END;
$function$;

CREATE OR REPLACE FUNCTION public.storage_unit_enforce_same_location(p_table text, p_operation text, p_new jsonb, p_old jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_parent_id       TEXT;
  v_parent_location TEXT;
  v_new_location    TEXT;
BEGIN
  IF p_operation NOT IN ('INSERT', 'UPDATE') THEN
    RETURN;
  END IF;

  v_parent_id := p_new->>'parentId';
  IF v_parent_id IS NULL THEN
    RETURN;
  END IF;

  v_new_location := p_new->>'locationId';

  SELECT "locationId"
  INTO v_parent_location
  FROM "storageUnit"
  WHERE "id" = v_parent_id;

  IF v_parent_location IS NULL THEN
    RAISE EXCEPTION 'Parent storage unit % does not exist', v_parent_id;
  END IF;

  IF v_parent_location <> v_new_location THEN
    RAISE EXCEPTION
      'Parent storage unit % is in location %, but this unit is in location %; they must match',
      v_parent_id, v_parent_location, v_new_location;
  END IF;
END;
$function$;

