CREATE OR REPLACE FUNCTION public.sync_job_complete_or_canceled(p_table text, p_operation text, p_new jsonb, p_old jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  group_ids TEXT[];
BEGIN
  IF p_operation = 'UPDATE'
    AND (p_old->>'status') != (p_new->>'status')
    AND ((p_new->>'status') = 'Completed' OR (p_new->>'status') = 'Cancelled')
  THEN
    UPDATE "kanban"
    SET "jobId" = NULL
    WHERE "jobId" = p_new->>'id';

    -- Send notification on job completion
    IF (p_new->>'status') = 'Completed' THEN
      IF (p_new->>'salesOrderId') IS NULL THEN
        SELECT "inventoryJobCompletedNotificationGroup" INTO group_ids
        FROM "companySettings" WHERE "id" = p_new->>'companyId';
      ELSE
        SELECT "salesJobCompletedNotificationGroup" INTO group_ids
        FROM "companySettings" WHERE "id" = p_new->>'companyId';
      END IF;

      IF (p_new->>'assignee') IS NOT NULL THEN
        group_ids := array_append(COALESCE(group_ids, '{}'), p_new->>'assignee');
      END IF;

      IF array_length(group_ids, 1) > 0 THEN
        PERFORM util.send_inngest_event(
          'carbon/notify',
          jsonb_build_object(
            'companyId', p_new->>'companyId',
            'documentId', p_new->>'id',
            'event', 'job-completed',
            'recipient', jsonb_build_object(
              'type', 'group',
              'groupIds', group_ids
            ),
            'from', 'system'
          )
        );
      END IF;
    END IF;
  END IF;
END;
$function$;

CREATE OR REPLACE FUNCTION public.sync_job_recompute_service_line(p_table text, p_operation text, p_new jsonb, p_old jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF p_operation != 'UPDATE' THEN RETURN; END IF;
  IF (p_new->>'salesOrderLineId') IS NULL THEN RETURN; END IF;

  -- Only when the completion state actually changed.
  IF (p_old->>'status') IS NOT DISTINCT FROM (p_new->>'status') THEN RETURN; END IF;
  IF NOT (
    (p_old->>'status') IN ('Completed', 'Closed')
    OR (p_new->>'status') IN ('Completed', 'Closed')
  ) THEN
    RETURN;
  END IF;

  PERFORM recompute_service_line_fulfillment(
    p_new->>'salesOrderLineId',
    p_new->>'companyId',
    p_new->>'updatedBy'
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public.sync_on_maintenance_dispatch_complete(p_table text, p_operation text, p_new jsonb, p_old jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
  IF p_operation != 'UPDATE' THEN RETURN; END IF;
  IF NOT ((p_new->>'status') = 'Completed' AND ((p_old->>'status') IS NULL OR (p_old->>'status') != 'Completed')) THEN
    RETURN;
  END IF;

  -- End all active events for this dispatch
  UPDATE "maintenanceDispatchEvent"
  SET
    "endTime" = COALESCE((p_new->>'completedAt')::timestamptz, NOW()),
    "updatedBy" = p_new->>'updatedBy',
    "updatedAt" = NOW()
  WHERE
    "maintenanceDispatchId" = p_new->>'id'
    AND "endTime" IS NULL;

  -- Set actualEndTime if not already set
  IF (p_new->>'actualEndTime') IS NULL THEN
    UPDATE "maintenanceDispatch"
    SET
      "actualEndTime" = NOW(),
      "updatedBy" = p_new->>'updatedBy',
      "updatedAt" = NOW()
    WHERE id = p_new->>'id';
  END IF;
END;
$function$;

CREATE OR REPLACE FUNCTION public.sync_propagate_item_readable_id_to_tracked_entity(p_table text, p_operation text, p_new jsonb, p_old jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
  IF p_operation != 'UPDATE' THEN RETURN; END IF;
  IF (p_new->>'readableIdWithRevision') IS NOT DISTINCT FROM (p_old->>'readableIdWithRevision') THEN
    RETURN;
  END IF;

  UPDATE "trackedEntity"
  SET "sourceDocumentReadableId" = p_new->>'readableIdWithRevision'
  WHERE "sourceDocument" = 'Item'
    AND "sourceDocumentId" = p_new->>'id';
END;
$function$;

CREATE OR REPLACE FUNCTION public.sync_protect_system_required_actions(p_table text, p_operation text, p_new jsonb, p_old jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
  IF p_operation = 'DELETE' THEN
    IF (p_old->>'systemType') IS NOT NULL THEN
      -- Allow cascading deletes when the parent company is being deleted
      IF NOT EXISTS (SELECT 1 FROM "company" WHERE id = p_old->>'companyId') THEN
        RETURN;
      END IF;
      RAISE EXCEPTION 'Cannot delete a system-defined required action. You may deactivate it instead.';
    END IF;
  END IF;

  IF p_operation = 'UPDATE' THEN
    IF (p_old->>'systemType') IS NOT NULL AND (p_new->>'systemType') IS DISTINCT FROM (p_old->>'systemType') THEN
      RAISE EXCEPTION 'Cannot change the systemType of a system-defined required action.';
    END IF;
    IF (p_old->>'systemType') IS NULL AND (p_new->>'systemType') IS NOT NULL THEN
      RAISE EXCEPTION 'Cannot assign a systemType to a custom required action.';
    END IF;
  END IF;
END;
$function$;

CREATE OR REPLACE FUNCTION public.sync_purchase_invoice_line_price_change(p_table text, p_operation text, p_new jsonb, p_old jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
  IF p_operation = 'UPDATE'
     AND ((p_new->>'unitPrice') IS DISTINCT FROM (p_old->>'unitPrice')
       OR (p_new->>'quantity') IS DISTINCT FROM (p_old->>'quantity'))
  THEN
    INSERT INTO "purchaseInvoicePriceChange" (
      "invoiceId", "invoiceLineId", "previousPrice", "newPrice",
      "previousQuantity", "newQuantity", "updatedBy"
    ) VALUES (
      p_new->>'invoiceId', p_new->>'id',
      (p_old->>'unitPrice')::numeric, (p_new->>'unitPrice')::numeric,
      (p_old->>'quantity')::numeric, (p_new->>'quantity')::numeric,
      COALESCE(p_new->>'updatedBy', p_new->>'createdBy')
    );
  END IF;
END;
$function$;

CREATE OR REPLACE FUNCTION public.sync_set_initial_dependency_status(p_table text, p_operation text, p_new jsonb, p_old jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
  IF p_operation != 'INSERT' THEN RETURN; END IF;

  -- Don't update if operation is already Done, In Progress, or Canceled
  IF EXISTS (
    SELECT 1
    FROM "jobOperation"
    WHERE id = p_new->>'operationId'
      AND status IN ('Done', 'In Progress', 'Canceled')
  ) THEN
    RETURN;
  END IF;

  -- Check if there are any incomplete dependencies
  IF EXISTS (
    SELECT 1
    FROM "jobOperationDependency" dep
    JOIN "jobOperation" jo ON jo.id = dep."dependsOnId"
    WHERE dep."operationId" = p_new->>'operationId'
      AND jo.status != 'Done'
  ) THEN
    UPDATE "jobOperation"
    SET status = 'Waiting'
    WHERE id = p_new->>'operationId';
  ELSE
    UPDATE "jobOperation"
    SET status = 'Ready'
    WHERE id = p_new->>'operationId';
  END IF;
END;
$function$;

CREATE OR REPLACE FUNCTION public.sync_set_job_operation_in_progress(p_table text, p_operation text, p_new jsonb, p_old jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF p_operation != 'INSERT' THEN RETURN; END IF;

  -- Only set to In Progress if endTime is NULL (event is starting, not already ended)
  IF (p_new->>'endTime') IS NULL THEN
    UPDATE "jobOperation"
    SET "status" = 'In Progress'
    WHERE id = p_new->>'jobOperationId';
  END IF;

  -- Set parent job to In Progress if it is still Ready
  UPDATE "job"
  SET "status" = 'In Progress'
  WHERE id = (
    SELECT "jobId" FROM "jobOperation" WHERE id = p_new->>'jobOperationId'
  )
  AND "status" = 'Ready';
END;
$function$;

CREATE OR REPLACE FUNCTION public.sync_update_customer_type_group(p_table text, p_operation text, p_new jsonb, p_old jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
  IF p_operation != 'UPDATE' THEN RETURN; END IF;

  IF p_old->>'customerTypeId' IS NOT NULL THEN
    IF p_new->>'customerTypeId' IS NOT NULL THEN
      UPDATE "membership" SET "groupId" = p_new->>'customerTypeId'
      WHERE "groupId" = p_old->>'customerTypeId' AND "memberGroupId" = p_new->>'id';
    ELSE
      DELETE FROM "membership"
      WHERE "groupId" = p_old->>'customerTypeId' AND "memberGroupId" = p_new->>'id';
    END IF;
  ELSE
    IF p_new->>'customerTypeId' IS NOT NULL THEN
      INSERT INTO "membership" ("groupId", "memberGroupId")
      VALUES (p_new->>'customerTypeId', p_new->>'id');
    END IF;
  END IF;

  UPDATE "group" SET "name" = p_new->>'name'
  WHERE "id" = p_new->>'id' AND "isCustomerOrgGroup" = TRUE;
END;
$function$;

